class SketchBasedJoinEstimatorConcurrentIncrementalTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:concurrent:predicate");

	@ParameterizedTest
	@CsvSource({ "CALLER,ADD", "CALLER,DELETE", "CALLER,READD", "BACKGROUND,ADD", "BACKGROUND,DELETE",
			"BACKGROUND,READD", "FULL_QUEUE,ADD", "FULL_QUEUE,DELETE" })
	void readersWaitForPreviouslyDrainedUpdates(Drain drain, Mutation mutation) throws Exception {
		Statement statement = VF.createStatement(VF.createIRI("urn:concurrent:subject"), PREDICATE,
				VF.createTripleTerm(PREDICATE, PREDICATE, VF.createLiteral("nested object")),
				VF.createIRI("urn:concurrent:context"));
		CopyOnWriteArrayList<Statement> source = new CopyOnWriteArrayList<>();
		if (mutation == Mutation.DELETE) {
			source.add(statement);
		}
		SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(
				(s, p, o, contexts) -> new CloseableIteratorIteration<>(source.iterator()),
				SketchBasedJoinEstimator.Config.defaults()
						.withNominalEntries(64)
						.withIncrementalQueueInitialLimit(drain == Drain.FULL_QUEUE ? 1 : 16)
						.withRefreshSleepMillis(1));
		BlockingStatement blocked = new BlockingStatement(statement);
		FutureTask<Double> first = null;
		FutureTask<Double> reader = new FutureTask<>(
				() -> estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, PREDICATE.stringValue()));
		try {
			estimator.rebuild();
			if (mutation == Mutation.DELETE) {
				assertEquals(1d, estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P,
						PREDICATE.stringValue()));
				source.clear();
				estimator.deleteStatement(blocked);
			} else {
				source.add(statement);
				estimator.addStatement(blocked);
				if (mutation == Mutation.READD) {
					estimator.deleteStatement(statement);
					estimator.addStatement(statement);
				}
			}
			if (drain == Drain.CALLER) {
				first = new FutureTask<>(() -> estimator.cardinalityPair(SketchBasedJoinEstimator.Pair.SP,
						statement.getSubject().stringValue(), PREDICATE.stringValue()));
				new Thread(first, "estimator-first-reader").start();
			} else if (drain == Drain.BACKGROUND) {
				estimator.startBackgroundRefresh(Integer.MAX_VALUE);
			}
			assertTrue(blocked.entered.await(5, TimeUnit.SECONDS), "The first drain must reach statement conversion");
			Thread readerThread = new Thread(reader, "estimator-concurrent-reader");
			readerThread.start();
			awaitBlockedOrFinished(readerThread);
			blocked.release.countDown();

			double expected = mutation == Mutation.DELETE ? 0d : 1d;
			assertEquals(expected, reader.get(5, TimeUnit.SECONDS),
					"A reader must include updates already drained by another caller or background task");
			if (first != null) {
				assertEquals(expected, first.get(5, TimeUnit.SECONDS));
			}
			assertEquals(expected, estimator.cardinalityPair(SketchBasedJoinEstimator.Pair.SP,
					statement.getSubject().stringValue(), PREDICATE.stringValue()));
		} finally {
			blocked.release.countDown();
			if (first != null) {
				first.get(5, TimeUnit.SECONDS);
			}
			estimator.close();
		}
	}

	@Test
	void updatesArrivingDuringCallerDrainRemainTrackedAcrossQueueRotation() throws Exception {
		SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(new StubSketchStatementSource(),
				SketchBasedJoinEstimator.Config.defaults().withNominalEntries(64).withIncrementalQueueInitialLimit(2));
		Statement statement = VF.createStatement(VF.createIRI("urn:concurrent:subject"), PREDICATE,
				VF.createLiteral("rotating queue"));
		BlockingStatement blocked = new BlockingStatement(statement);
		FutureTask<Double> first = new FutureTask<>(
				() -> estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, PREDICATE.stringValue()));
		FutureTask<Double> reader = new FutureTask<>(
				() -> estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, PREDICATE.stringValue()));
		try {
			estimator.addStatement(blocked);
			new Thread(first, "estimator-rotating-caller").start();
			assertTrue(blocked.entered.await(5, TimeUnit.SECONDS));
			// The active queue still accepts rows while the caller converts its drained batch.
			estimator.deleteStatement(statement);
			estimator.addStatement(statement);
			Thread readerThread = new Thread(reader, "estimator-rotating-reader");
			readerThread.start();
			awaitBlockedOrFinished(readerThread);
			blocked.release.countDown();
			assertEquals(1d, reader.get(5, TimeUnit.SECONDS));
			assertEquals(1d, first.get(5, TimeUnit.SECONDS));
			assertEquals(1d, estimator.cardinalityPair(SketchBasedJoinEstimator.Pair.SP,
					statement.getSubject().stringValue(), PREDICATE.stringValue()));
		} finally {
			blocked.release.countDown();
			first.get(5, TimeUnit.SECONDS);
			estimator.close();
		}
	}

	@Test
	void failedDrainReleasesWaitingReadersAndAllowsRebuild() throws Exception {
		SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(new StubSketchStatementSource(),
				SketchBasedJoinEstimator.Config.defaults().withNominalEntries(64));
		Statement statement = VF.createStatement(VF.createIRI("urn:concurrent:subject"), PREDICATE,
				VF.createLiteral("conversion failure"));
		IllegalStateException failure = new IllegalStateException("injected statement conversion failure");
		BlockingStatement blocked = new BlockingStatement(statement, failure);
		FutureTask<Void> first = new FutureTask<>(() -> {
			estimator.debugFlushPendingIncremental();
			return null;
		});
		FutureTask<Double> reader = new FutureTask<>(
				() -> estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P, PREDICATE.stringValue()));
		try {
			estimator.addStatement(blocked);
			new Thread(first, "estimator-failed-drain").start();
			assertTrue(blocked.entered.await(5, TimeUnit.SECONDS));
			Thread readerThread = new Thread(reader, "estimator-failed-drain-reader");
			readerThread.start();
			awaitBlockedOrFinished(readerThread);
			blocked.release.countDown();
			assertSame(failure,
					assertThrows(ExecutionException.class, () -> first.get(5, TimeUnit.SECONDS)).getCause());
			assertSame(failure,
					assertThrows(ExecutionException.class, () -> reader.get(5, TimeUnit.SECONDS)).getCause());

			// Recovery waits for all reservations to retire before clearing the recorded failure.
			estimator.discardAndMarkForRebuild();
			estimator.rebuild();
			estimator.addStatement(statement);
			assertEquals(1d, estimator.cardinalitySingle(SketchBasedJoinEstimator.Component.P,
					PREDICATE.stringValue()));
		} finally {
			blocked.release.countDown();
			estimator.discardAndMarkForRebuild();
			estimator.close();
		}
	}

	private static void awaitBlockedOrFinished(Thread thread) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (thread.isAlive() && thread.getState() != Thread.State.WAITING
				&& thread.getState() != Thread.State.BLOCKED && System.nanoTime() < deadline) {
			Thread.yield();
		}
		assertTrue(!thread.isAlive() || thread.getState() == Thread.State.WAITING
				|| thread.getState() == Thread.State.BLOCKED, "The reader must reach the drain barrier or finish");
	}

	private enum Drain {
		CALLER,
		BACKGROUND,
		FULL_QUEUE
	}

	private enum Mutation {
		ADD,
		DELETE,
		READD
	}

	private static final class BlockingStatement extends AbstractStatement {
		private static final long serialVersionUID = 1L;
		private final Statement delegate;
		private final RuntimeException failure;
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);

		private BlockingStatement(Statement delegate) {
			this(delegate, null);
		}

		private BlockingStatement(Statement delegate, RuntimeException failure) {
			this.delegate = delegate;
			this.failure = failure;
		}

		@Override
		public Resource getSubject() {
			entered.countDown();
			try {
				assertTrue(release.await(5, TimeUnit.SECONDS), "The test must release statement conversion");
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new AssertionError(e);
			}
			if (failure != null) {
				throw failure;
			}
			return delegate.getSubject();
		}

		@Override
		public IRI getPredicate() {
			return delegate.getPredicate();
		}

		@Override
		public Value getObject() {
			return delegate.getObject();
		}

		@Override
		public Resource getContext() {
			return delegate.getContext();
		}
	}
}
